effect.shader:
void main() {
    vec2 res = vec2(acAspect, 1.0);
    vec2 cell = vec2(size) * acTexelSize * acEscalaDePixel;
    vec2 q = floor(acScreenNorm / cell) * cell + cell * 0.5;

    vec4 bloco = texture(inputImg, q);
    vec4 real  = texture(inputImg, acScreenNorm);

    // suaviza misturando a cor do bloco com a original pela distância ao centro
    vec2 f = fract(acScreenNorm / cell) - 0.5;
    float d = max(abs(f.x), abs(f.y));
    float k = smoothstep(0.5 - softness * 0.5, 0.5, d);
    fragColor = mix(bloco, real, k * softness);
}
